def motion_for(concept_id):
    name, recipe, period, subject, purpose = TREATMENTS[concept_id]
    rotation = recipe in ('outer-gimbal', 'cage-precession', 'reference-ring-trace')
    oscillation = recipe in ('tangent-bracket', 'counterframe-slide', 'page-edge-parallax')
    formula = ('theta = 2 * pi * elapsedSeconds / periodSeconds' if rotation else
               'offset = amplitude * sin(2 * pi * elapsedSeconds / periodSeconds)' if oscillation else
               'pathU = fract(elapsedSeconds / periodSeconds + fixedCategoryPhase)')
    return {
        'treatment': name, 'recipe': recipe,
        'measured': {'type': 'none', 'reason': 'No animated rate, physical flow, trend or forecast is inferred. Actual historical rows remain user-selectable static observations.'},
        'decorative': {'subject': subject, 'purpose': purpose, 'periodSeconds': period,
                       'formula': formula, 'amplitude': 'At most 0.012 globe radii translation or 2 degrees cover tilt; no scale change.' if oscillation else 'Constant-radius exterior motion; no data displacement.',
                       'renderLayer': 'Dedicated non-data group, depth tested behind or outside marks; no coastlines, values, marks or uncertainty endpoints in this group.',
                       'material': 'Unlit neutral hairline, opacity 0.22 to 0.32 constant; no emissive pulse, bloom, flash, opacity beat or changing quantitative colour.',
                       'label': 'Ambient frame motion — not measured change',
                       'maximumExtraDrawCalls': 2, 'maximumExtraTriangles': 2000},
        'invariants': ['Every data position, extent, area, value, colour scale and interval endpoint is constant during one decorative loop.',
                       'Category order, geographic coordinates, source period and status remain constant.',
                       'The loop neither hides a value nor cycles selection, labels, source limitations or keyboard focus.',
                       'All repeated decorative frames have identical speed and amplitude regardless of the measured value.'],
        'controls': 'Visible Pause motion control persists. Pause immediately on pointer/touch/key interaction, tab hiding, canvas leaving the viewport or route exit. Resume only by explicit Play after interaction. Camera does not autorotate without the separate Spin action.',
        'reducedMotion': 'Never start the loop when prefers-reduced-motion is active. Keep the full data geometry and one neutral static scaffold at phase 0; direct rotation and table navigation update immediately without inertia or animation.',
        'mobile': 'Run only the selected visible globe at a 30 fps target. Disable decorative loop before reducing data marks if the named-device budget is missed; retain static SVG/table fallback.',
        'validation': ['Snapshot data transforms and materials at phase 0, 0.25, 0.5 and 0.75; assert byte-equivalent measurement state.',
                       'Pause and reduced-motion leave every value, qualifier, uncertainty interval and table row accessible.',
                       'No motion speed or phase depends on value, status, geographic position or source date.',
                       'No animation frame changes selection, announces live values or restarts after explicit Pause.']
    }
